+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+
+/**
+ * Filters for the customer list.
+ *
+ * @param nameTerms split, normalized name filter terms; empty means no filter
+ * @param statuses  selected statuses; empty means all statuses
+ */
+public record CustomerFilter(List<String> nameTerms, List<CustomerStatus> statuses) {
+
+    /**
+     * Normalize a string for accent-insensitive, case-insensitive matching.
+     */
+    public static String normalize(String s) {
+        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
+        return decomposed.replaceAll("\\p{M}", "").toLowerCase();
+    }
+
+    /**
+     * Parse a name filter from user input: split on whitespace, normalize, and remove empties.
+     */
+    public static List<String> parseNameFilter(String input) {
+        if (input == null || input.isBlank()) {
+            return List.of();
+        }
+        return Arrays.stream(input.split("\\s+"))
+                .map(CustomerFilter::normalize)
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /**
+     * Check if a customer matches this filter.
+     */
+    public boolean matches(Customer customer) {
+        if (!nameTerms.isEmpty()) {
+            String normalizedFirst = normalize(customer.firstName());
+            String normalizedLast = normalize(customer.lastName());
+            for (String term : nameTerms) {
+                if (!normalizedFirst.contains(term) && !normalizedLast.contains(term)) {
+                    return false;
+                }
+            }
+        }
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        return true;
+    }
+}
