+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Arrays;
+import java.util.List;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerRepository;
+import com.example.customers.domain.CustomerSort;
+import com.example.customers.domain.CustomerStatus;
+import com.example.customers.domain.QueryLog;
+import com.example.customers.service.CustomerService;
+
+import com.example.Application;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+
+/**
+ * Tests for the customer filtering functionality.
+ */
+@SpringBootTest(classes = Application.class)
+class FilteringTest {
+
+    @Autowired
+    private CustomerService customerService;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @BeforeEach
+    void setUp() {
+        queryLog.clear();
+    }
+
+    @Test
+    void filterByNameSubstring() {
+        // "ada" should match "Ada Aaltonen"
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("ada"), Arrays.asList(CustomerStatus.values()));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().anyMatch(c -> c.firstName().equalsIgnoreCase("Ada") && c.lastName().equalsIgnoreCase("Aaltonen")));
+    }
+
+    @Test
+    void filterByNameCaseInsensitive() {
+        // "ADA" should match "Ada Aaltonen"
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("ADA"), Arrays.asList(CustomerStatus.values()));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().anyMatch(c -> c.firstName().equalsIgnoreCase("Ada") && c.lastName().equalsIgnoreCase("Aaltonen")));
+    }
+
+    @Test
+    void filterByNameAccentInsensitive() {
+        // "makinen" should match "Mäkinen"
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("makinen"), Arrays.asList(CustomerStatus.values()));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().anyMatch(c -> c.lastName().contains("äk")));
+    }
+
+    @Test
+    void filterByMultipleNameTerms() {
+        // "ada aal" should match "Ada Aaltonen"
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("ada aal"), Arrays.asList(CustomerStatus.values()));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().anyMatch(c -> c.firstName().equalsIgnoreCase("Ada") && c.lastName().equalsIgnoreCase("Aaltonen")));
+    }
+
+    @Test
+    void filterByMultipleNameTermsInReverseOrder() {
+        // "aal ada" should match "Ada Aaltonen"
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("aal ada"), Arrays.asList(CustomerStatus.values()));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().anyMatch(c -> c.firstName().equalsIgnoreCase("Ada") && c.lastName().equalsIgnoreCase("Aaltonen")));
+    }
+
+    @Test
+    void filterByNameNoMatch() {
+        // "xyz" should not match anyone
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("xyz"), Arrays.asList(CustomerStatus.values()));
+        int count = customerService.count(filter);
+
+        assertEquals(0, count);
+    }
+
+    @Test
+    void filterByStatus() {
+        // Filter by ACTIVE status only
+        CustomerFilter filter = new CustomerFilter(List.of(), List.of(CustomerStatus.ACTIVE));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().allMatch(c -> c.status() == CustomerStatus.ACTIVE));
+    }
+
+    @Test
+    void filterByMultipleStatuses() {
+        // Filter by ACTIVE or PENDING
+        CustomerFilter filter = new CustomerFilter(List.of(), List.of(CustomerStatus.ACTIVE, CustomerStatus.PENDING));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().allMatch(c -> c.status() == CustomerStatus.ACTIVE || c.status() == CustomerStatus.PENDING));
+    }
+
+    @Test
+    void filterByNameAndStatus() {
+        // Filter by name "ada" and ACTIVE status
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("ada"), List.of(CustomerStatus.ACTIVE));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        assertTrue(results.stream().allMatch(c ->
+            (c.firstName().toLowerCase().contains("ada") || c.lastName().toLowerCase().contains("ada")) &&
+            c.status() == CustomerStatus.ACTIVE
+        ));
+    }
+
+    @Test
+    void noFilterReturnsAll() {
+        // No filter should return all customers
+        CustomerFilter filter = new CustomerFilter(List.of(), List.of());
+        int count = customerService.count(filter);
+
+        assertEquals(500, count);
+    }
+
+    @Test
+    void emptyNameFilterMatchesAll() {
+        // Empty name filter should match all customers (when there's a status filter)
+        CustomerFilter filter = new CustomerFilter(List.of(), List.of(CustomerStatus.ACTIVE));
+        var results = customerService.list(0, 200, List.of(), filter);
+
+        // Verify we got results and they're all ACTIVE
+        assertTrue(results.stream().allMatch(c -> c.status() == CustomerStatus.ACTIVE));
+    }
+
+    @Test
+    void filterStaysLazyLoaded() {
+        // Filtering should still use lazy loading
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("ada"), List.of());
+        customerService.list(0, 50, List.of(), filter);
+
+        // Should only fetch one page
+        assertEquals(1, queryLog.pageQueries().size());
+        assertTrue(queryLog.pageQueries().get(0).limit() <= CustomerRepository.MAX_PAGE_SIZE);
+    }
+
+    @Test
+    void filterCountQueriesWork() {
+        // Count queries should work with filters
+        CustomerFilter filter = new CustomerFilter(CustomerFilter.parseNameFilter("ada"), List.of());
+        int count = customerService.count(filter);
+
+        assertTrue(count > 0);
+        assertTrue(count <= 500);
+        assertFalse(queryLog.countQueries().isEmpty());
+    }
+}
