+import org.springframework.boot.test.context.SpringBootTest;
+
+/**
+ * UI tests for customer filtering in the grid.
+ */
+@SpringBootTest(classes = Application.class,
+        webEnvironment = SpringBootTest.WebEnvironment.MOCK)
+class FilteringUITest extends SpringBrowserlessTest {
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @BeforeEach
+    void setUpVaadin() {
+        navigate("", Component.class);
+        queryLog.clear();
+    }
+
+    @Test
+    void filterUIComponentsExist() {
+        TextField nameFilter = find(TextField.class).all().stream()
+                .filter(f -> "Filter by name".equals(f.getPlaceholder()))
+                .findFirst()
+                .orElse(null);
+        assertNotNull(nameFilter, "Name filter TextField should exist");
+
+        MultiSelectComboBox<?> statusFilter = find(MultiSelectComboBox.class).single();
+        assertNotNull(statusFilter, "Status filter MultiSelectComboBox should exist");
+    }
+
+    @Test
+    void summaryComponentExists() {
+        Span summary = find(Span.class).all().stream()
+                .filter(s -> s.getText().startsWith("Showing"))
+                .findFirst()
+                .orElse(null);
+        assertNotNull(summary, "Summary component should exist");
+    }
+
+    @Test
+    void initialSummaryShowsAllCustomers() {
+        Span summary = find(Span.class).all().stream()
+                .filter(s -> s.getText().startsWith("Showing"))
+                .findFirst()
+                .orElse(null);
+        assertNotNull(summary);
+        assertEquals("Showing 500 of 500", summary.getText());
+    }
+
+    @Test
+    void gridStillShowsRows() {
+        Grid<?> grid = find(Grid.class).single();
+        assertTrue(test(grid).size() > 0);
+    }
+
+    @Test
+    void gridIsLazilyLoaded() {
+        Grid<?> grid = find(Grid.class).single();
+        test(grid).getCellText(0, 0);
+
+        assertTrue(queryLog.pageQueries().size() > 0,
+                "Grid must fetch rows from backend");
+        assertTrue(queryLog.rowsFetched() <= 200,
+                "Grid must fetch only one page of rows");
+    }
